items.content:
[
  {
    "name": "read",
    "description": "读取工作区内文件的全部内容",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "相对工作区根的路径"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "write",
    "description": "写入文件（覆盖式，自动创建父目录）。需用户授权",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "相对工作区根的路径"
        },
        "content": {
          "type": "string",
          "description": "完整文件内容"
        }
      },
      "required": [
        "path",
        "content"
      ]
    }
  },
  {
    "name": "edit",
    "description": "对文件做精确的字符串替换（old_string 须唯一，除非 replace_all=true）。需用户授权",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "相对工作区根的路径"
        },
        "old_string": {
          "type": "string",
          "description": "被替换的原文（非空）"
        },
        "new_string": {
          "type": "string",
          "description": "替换后的文本（可为空串表示删除）"
        },
        "replace_all": {
          "type": "boolean",
          "description": "替换全部出现位置"
        }
      },
      "required": [
        "path",
        "old_string",
        "new_string"
      ]
    }
  },
  {
    "name": "bash",
    "description": "在工作区根目录执行 shell 命令并返回输出。需用户授权",
    "parameters": {
      "type": "object",
      "properties": {
        "command": {
          "type": "string",
          "description": "要执行的命令"
        },
        "timeout_ms": {
          "type": "number",
          "description": "超时毫秒数（可选）"
        }
      },
      "required": [
        "command"
      ]
    }
  },
  {
    "name": "grep",
    "description": "在工作区文件中按正则搜索，输出 文件:行号: 内容",
    "parameters": {
      "type": "object",
      "properties": {
        "pattern": {
          "type": "string",
          "description": "正则表达式"
        },
        "path": {
          "type": "string",
          "description": "起始目录（默认工作区根）"
        },
        "glob": {
          "type": "string",
          "description": "文件名通配过滤，如 *.ts"
        },
        "case_sensitive": {
          "type": "boolean",
          "description": "大小写敏感（默认 true）"
        }
      },
      "required": [
        "pattern"
      ]
    }
  },
  {
    "name": "find",
    "description": "按文件名通配符（* / ?）查找文件与目录",
    "parameters": {
      "type": "object",
      "properties": {
        "pattern": {
          "type": "string",
          "description": "文件名通配符，如 *.ts"
        },
        "path": {
          "type": "string",
          "description": "起始目录（默认工作区根）"
        }
      },
      "required": [
        "pattern"
      ]
    }
  },
  {
    "name": "ls",
    "description": "列出目录内容（目录名带 / 后缀）",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "目录路径（默认工作区根）"
        }
      }
    }
  }
]
